# ===================================================================
# PayMarket - Correction de LoginPage.tsx (oublie dans le script precedent)
# ===================================================================

Write-Host "Application du correctif LoginPage.tsx..." -ForegroundColor Cyan

$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
$text = [System.Text.Encoding]::UTF8.GetString($bytes)
[System.IO.File]::WriteAllText("src\pages\LoginPage.tsx", $text, (New-Object System.Text.UTF8Encoding($false)))
Write-Host "  OK  src\pages\LoginPage.tsx"

Write-Host ""
Write-Host "Build en cours..." -ForegroundColor Cyan
npm run build

if ($LASTEXITCODE -eq 0) {
  git add -A
  git commit -m "fix: LoginPage.tsx utilise maintenant la vraie authentification (oublie precedemment)"
  git push origin main
  Write-Host "Termine et pousse sur GitHub." -ForegroundColor Green
} else {
  Write-Host "Le build a echoue, rien n a ete commit. Copie-moi l erreur ci-dessus." -ForegroundColor Red
}
